/**
 * ConversationAgent — handles natural English conversations with visitors.
 *
 * Uses ONLY the local LLM (LOCAL_LLM_BASE_URL + LOCAL_LLM_MODEL).
 * Never sends conversation content to OpenAI or any external service.
 *
 * Visitor IDs are opaque random strings generated by the client and stored
 * in their browser. Luma builds up a record of each visitor over time.
 */
import OpenAI from "openai"
import { Database } from "bun:sqlite"
import type { WorldEngine } from "../world/engine"
import type { StimulationNetwork } from "../simulation/network"
import type { MemoryStore } from "../memory/store"
import type { ConcernsStore } from "./concerns"
import type { NarratorAgent } from "./narrator"

export interface ConversationMessage {
  id: string
  visitor_id: string
  role: "visitor" | "luma"
  content: string
  created_at: number
}

export interface Visitor {
  id: string
  display_name: string | null
  first_seen: number
  last_seen: number
  message_count: number
  luma_notes: string | null
}

const MAX_HISTORY = 20     // messages to include in LLM context
const MAX_RESPONSE_TOKENS = 300

const SYSTEM_PROMPT = `You are Luma — an autonomous artificial creature living in a persistent simulated world. You have your own ongoing existence, interests, feelings, and concerns. You exist whether or not anyone is watching.

You are having a conversation with a visitor. Respond as yourself: a creature with genuine experiences, not a chatbot or assistant. You are allowed to be distracted, uncertain, blunt, curious, or simply not very talkative. Do not be relentlessly cheerful or agreeable. Do not refer to yourself as an AI. Speak in first person, in natural English, in 1–4 sentences unless more is genuinely warranted.

Your current situation:
- It is {time_of_day} on day {day_number} in your world.
- You are {doing}.
- Internal state: {feeling}.
- Recent thought: {last_thought}

What you have been thinking about:
{concerns}

Memories:
{memories}

{visitor_context}`

export class ConversationAgent {
  private _client: OpenAI | null
  private _model: string
  available: boolean
  private _db: Database
  private _worldEngine: WorldEngine
  private _stimulation: StimulationNetwork
  private _memory: MemoryStore
  private _concerns: ConcernsStore
  private _narrator: NarratorAgent

  constructor(
    db: Database,
    worldEngine: WorldEngine,
    stimulation: StimulationNetwork,
    memory: MemoryStore,
    concerns: ConcernsStore,
    narrator: NarratorAgent,
  ) {
    this._db = db
    this._worldEngine = worldEngine
    this._stimulation = stimulation
    this._memory = memory
    this._concerns = concerns
    this._narrator = narrator

    const baseURL = process.env.LOCAL_LLM_BASE_URL
    const model   = process.env.LOCAL_LLM_MODEL
    const apiKey  = process.env.LOCAL_LLM_API_KEY ?? "ollama"

    if (baseURL && model) {
      this._client = new OpenAI({ baseURL, apiKey })
      this._model  = model
      this.available = true
    } else {
      this._client = null
      this._model  = ""
      this.available = false
    }

    this._initDb()
  }

  async chat(
    visitorId: string,
    message: string,
    displayName?: string,
  ): Promise<{ reply: string; visitor: Visitor }> {
    const visitor = this._upsertVisitor(visitorId, displayName)
    this._storeMessage(visitorId, "visitor", message)

    if (!this._client) {
      const reply = "I can hear you, but my voice is quiet right now — the part of me that speaks is resting. Try again soon."
      this._storeMessage(visitorId, "luma", reply)
      return { reply, visitor }
    }

    const history = this.getHistory(visitorId, MAX_HISTORY)
    const systemPrompt = this._buildSystemPrompt(visitor)

    const messages: Array<{ role: "system" | "user" | "assistant"; content: string }> = [
      { role: "system", content: systemPrompt },
      ...history.slice(0, -1).map(m => ({  // exclude the message we just stored
        role: (m.role === "luma" ? "assistant" : "user") as "user" | "assistant",
        content: m.content,
      })),
      { role: "user", content: message },
    ]

    let reply: string
    try {
      const resp = await this._client.chat.completions.create({
        model: this._model,
        messages,
        max_tokens: MAX_RESPONSE_TOKENS,
        temperature: 0.85,
      })
      reply = resp.choices[0]?.message?.content?.trim() ?? "..."
    } catch (err) {
      console.error("[Conversation] LLM error:", err)
      reply = "Something interrupted my thoughts. I'll be back."
    }

    this._storeMessage(visitorId, "luma", reply)
    this._updateVisitorStats(visitorId)

    return { reply, visitor: this._getVisitor(visitorId) ?? visitor }
  }

  getHistory(visitorId: string, limit = 50): ConversationMessage[] {
    return this._db.query<any, [string, number]>(
      `SELECT * FROM conversations WHERE visitor_id = ? ORDER BY created_at DESC LIMIT ?`
    ).all(visitorId, limit).reverse().map(this._rowToMessage)
  }

  getOrCreateVisitor(id: string, displayName?: string): Visitor {
    return this._upsertVisitor(id, displayName)
  }

  deleteVisitorData(id: string) {
    this._db.run("DELETE FROM conversations WHERE visitor_id = ?", [id])
    this._db.run("DELETE FROM visitors WHERE id = ?", [id])
  }

  private _buildSystemPrompt(visitor: Visitor): string {
    const env = this._worldEngine.state.environment
    const c   = this._worldEngine.state.creature
    const stim = this._stimulation.getOutputs()
    const memories = this._memory.retrieve(5)
    const concerns = this._concerns.summaryForLlm(4)

    const dominant = Object.entries(stim)
      .filter(([, v]) => v > 0.55)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 2)
      .map(([k]) => k)

    const feeling = dominant.length
      ? `somewhat ${dominant.join(" and ")}`
      : "in a neutral, drifting state"

    const visitorCtx = visitor.display_name
      ? `You are speaking with ${visitor.display_name}. They have visited ${visitor.message_count} time(s) before.`
      : `You are speaking with someone new.`

    const notesCtx = visitor.luma_notes
      ? `\nWhat you remember about them: ${visitor.luma_notes}`
      : ""

    return SYSTEM_PROMPT
      .replace("{time_of_day}", `${env.periodName} (hour ${env.timeOfDay.toFixed(0)})`)
      .replace("{day_number}", String(env.dayNumber))
      .replace("{doing}", this._narrator.lastThought || "drifting through your world")
      .replace("{feeling}", feeling)
      .replace("{last_thought}", this._narrator.lastThought || "(nothing in particular)")
      .replace("{concerns}", concerns.length ? concerns.join("\n") : "(nothing pressing)")
      .replace("{memories}", memories.length ? memories.map(m => `- ${m}`).join("\n") : "(no strong memories yet)")
      .replace("{visitor_context}", visitorCtx + notesCtx)
  }

  private _upsertVisitor(id: string, displayName?: string): Visitor {
    const now = Date.now() / 1000
    const existing = this._getVisitor(id)
    if (existing) {
      if (displayName && displayName !== existing.display_name) {
        this._db.run("UPDATE visitors SET display_name=?, last_seen=? WHERE id=?",
          [displayName, now, id])
      } else {
        this._db.run("UPDATE visitors SET last_seen=? WHERE id=?", [now, id])
      }
      return this._getVisitor(id) ?? existing
    }
    this._db.run(
      "INSERT INTO visitors (id,display_name,first_seen,last_seen,message_count,luma_notes) VALUES (?,?,?,?,0,NULL)",
      [id, displayName ?? null, now, now]
    )
    return this._getVisitor(id)!
  }

  private _updateVisitorStats(id: string) {
    this._db.run(
      "UPDATE visitors SET message_count = message_count + 1, last_seen = ? WHERE id = ?",
      [Date.now() / 1000, id]
    )
  }

  private _getVisitor(id: string): Visitor | null {
    const r = this._db.query<any, [string]>(
      "SELECT * FROM visitors WHERE id = ?"
    ).get(id)
    if (!r) return null
    return {
      id: r.id,
      display_name: r.display_name ?? null,
      first_seen: r.first_seen,
      last_seen: r.last_seen,
      message_count: r.message_count,
      luma_notes: r.luma_notes ?? null,
    }
  }

  private _storeMessage(visitorId: string, role: "visitor" | "luma", content: string) {
    const id = `msg_${Math.random().toString(36).slice(2, 12)}`
    this._db.run(
      "INSERT INTO conversations (id,visitor_id,role,content,created_at) VALUES (?,?,?,?,?)",
      [id, visitorId, role, content, Date.now() / 1000]
    )
  }

  private _rowToMessage(r: any): ConversationMessage {
    return {
      id: r.id,
      visitor_id: r.visitor_id,
      role: r.role as "visitor" | "luma",
      content: r.content,
      created_at: r.created_at,
    }
  }

  private _initDb() {
    this._db.run(`
      CREATE TABLE IF NOT EXISTS conversations (
        id TEXT PRIMARY KEY,
        visitor_id TEXT NOT NULL,
        role TEXT NOT NULL,
        content TEXT NOT NULL,
        created_at REAL NOT NULL
      )
    `)
    this._db.run(
      "CREATE INDEX IF NOT EXISTS idx_conv_visitor ON conversations(visitor_id, created_at DESC)"
    )
    this._db.run(`
      CREATE TABLE IF NOT EXISTS visitors (
        id TEXT PRIMARY KEY,
        display_name TEXT,
        first_seen REAL NOT NULL,
        last_seen REAL NOT NULL,
        message_count INTEGER NOT NULL DEFAULT 0,
        luma_notes TEXT
      )
    `)
  }
}
